"""Plain-language summaries of parsed lab results, generated by a local Ollama model.

Which results are high or low is decided here in Python, from the report's own
flags and reference ranges, so the model only explains results — it never has
to read values or judge ranges itself.
"""

import os

import ollama

OLLAMA_MODEL = os.environ.get("OLLAMA_MODEL", "qwen2.5vl:7b")

SYSTEM_PROMPT = (
    "You explain blood test results to a patient in plain, calm language. "
    "Only use the values and statuses given. Do not diagnose and do not recommend treatments."
)

# Small local models follow a fill-in-the-blanks skeleton in the user message
# far more reliably than format rules in the system prompt.
INSTRUCTIONS = (
    "Write the summary in exactly this format:\n\n"
    "<one or two sentences on the overall picture>\n\n"
    "Results outside the normal range:\n"
    "- <test> (<value>, <high/low>): <what the test measures>. "
    "<what a high or low value commonly relates to>.\n"
    "<one bullet like this for EVERY out-of-range result above>\n\n"
    "Normal results: <one sentence on which areas were normal>\n\n"
    "Please review these results with your doctor."
)

llm = ollama.Client()


def result_status(result):
    """HIGH / LOW / ABNORMAL from the report's flag, else from the reference range.

    "unknown" when there is neither, so a result is never called normal without
    a range to back it up.
    """
    flag = result.get("flag")
    if flag in ("H", "HH"):
        return "HIGH"
    if flag in ("L", "LL"):
        return "LOW"
    if flag:
        return "ABNORMAL"
    # A value like ">60" can't be compared precisely, so trust the (absent) flag.
    if result.get("value_text", "")[:1] in "<>":
        return "normal"
    value, low, high = result.get("value"), result.get("ref_low"), result.get("ref_high")
    if value is None or (low is None and high is None):
        return "unknown"
    if high is not None and value > high:
        return "HIGH"
    if low is not None and value < low:
        return "LOW"
    return "normal"


def _describe(result):
    name = result.get("canonical") or result.get("test")
    value = " ".join(filter(None, [result.get("value_text"), result.get("unit")]))
    ref = f" (reference {result['reference_range']})" if result.get("reference_range") else ""
    return f"- {name}: {value}{ref} — {result_status(result)}"


def format_panels(panels):
    """"Complete Blood Count (complete); Iron Studies (not tested: Ferritin)" for the detected panels."""
    return "; ".join(
        p["name"] + (f" (not tested: {', '.join(p['missing'])})" if p["missing"] else " (complete)")
        for p in panels
    )


def format_results(results, panels=()):
    """Out-of-range results listed in full first, so the model can't skip them."""
    def names(status):
        return ", ".join(r.get("canonical") or r.get("test") for r in results if result_status(r) == status)

    abnormal = [_describe(r) for r in results if result_status(r) not in ("normal", "unknown")]
    return (
        (f"Test panels in this report: {format_panels(panels)}\n\n" if panels else "")
        + f"Out-of-range results ({len(abnormal)}):\n" + ("\n".join(abnormal) or "None")
        + "\n\nNormal results: " + (names("normal") or "None")
        + "\n\nResults with no reference range (do not call these normal or abnormal): "
        + (names("unknown") or "None")
        + "\n\n" + INSTRUCTIONS
    )


def stream_summary(results, panels=()):
    """Yield the summary text in chunks as the model generates it.

    The first chunk is requested eagerly so connection/model errors raise
    here, before the caller starts a streaming response.
    """
    stream = llm.chat(
        model=OLLAMA_MODEL,
        messages=[
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": format_results(results, panels)},
        ],
        stream=True,
        keep_alive="30m",
        options={"temperature": 0.2, "num_ctx": 4096, "num_predict": 600},
    )
    first = next(stream).message.content

    def chunks():
        yield first
        for part in stream:
            yield part.message.content

    return chunks()
